import React, { useState } from "react";

/**
 * Intro Component:
 * Full-screen entrance greeting.
 * Clicking "Open the surprise" starts audio playback safely upon user gesture,
 * triggers celebratory sparkles, and smoothly slides into the reveal.
 */
export const Intro = ({ config, onOpen, isOpened }) => {
  const [isExiting, setIsExiting] = useState(false);

  const handleOpen = () => {
    setIsExiting(true);
    // Smooth transition delay to let button ripple & audio trigger
    setTimeout(() => {
      onOpen();
    }, 400);
  };

  return (
    <section
      id="intro"
      className={`intro-screen ${isOpened ? "intro-opened" : ""} ${
        isExiting ? "intro-exiting" : ""
      }`}
      aria-label="Welcome screen"
    >
      <div className="intro-backdrop-glow" aria-hidden="true" />

      <div className="intro-content">
        <span className="intro-eyebrow">{config.intro.eyebrow}</span>

        <h1 className="intro-title">{config.intro.title}</h1>

        <p className="intro-subtitle">{config.intro.subtitle}</p>

        <div className="intro-action">
          <button
            type="button"
            className="intro-btn"
            onClick={handleOpen}
            aria-label="Open the birthday surprise experience"
          >
            <span className="btn-text">{config.intro.buttonText}</span>
            <span className="btn-icon" aria-hidden="true">
              <svg
                width="18"
                height="18"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="1.5"
                strokeLinecap="round"
                strokeLinejoin="round"
              >
                <path d="M5 12h14" />
                <path d="m12 5 7 7-7 7" />
              </svg>
            </span>
            <span className="btn-glow" aria-hidden="true" />
          </button>
        </div>

        <div className="intro-hint" aria-hidden="true">
          <span>Headphones recommended for music</span>
        </div>
      </div>
    </section>
  );
};

export default Intro;
